#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);project<-normalizePath(args[1]);base<-file.path(project,'paper19opp-revision2')
.libPaths(c(file.path(project,'.Rlib'),.libPaths()));suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork);library(svglite);library(ragg)})
results<-file.path(base,'reconstruction/upr_rpe1_validation');source_dir<-file.path(base,'reconstruction/cross_dataset/phase2_upr_rpe1');archive<-file.path(base,'reconstruction/cross_dataset/figures');source_data<-file.path(base,'reconstruction/cross_dataset/figure_source_data')
blue<-'#4C78A8';grey<-'#7D858D';ink<-'#282828';font<-'Helvetica'
theme_pub<-function(){theme_classic(base_size=7,base_family=font)+theme(axis.line=element_line(linewidth=.3,colour=ink),axis.ticks=element_line(linewidth=.3,colour=ink),axis.ticks.length=grid::unit(1,'mm'),axis.text=element_text(size=7,colour=ink),axis.title=element_text(size=7,colour=ink),plot.tag=element_text(size=8,face='bold',family=font),plot.tag.position=c(0,1),strip.background=element_blank(),strip.text=element_text(size=7,colour=ink),legend.title=element_blank(),legend.text=element_text(size=7),legend.key.size=grid::unit(3,'mm'),legend.spacing.x=grid::unit(1,'mm'),plot.margin=margin(5,5,4,4),panel.grid=element_blank())}
state<-readRDS(file.path(results,'phase2_statistical_state.rds'));primary<-fread(file.path(results,'primary_Holm3_endpoints.tsv'));fixed<-fread(file.path(results,'fixed_list_direction_absolute_summaries.tsv'))
input<-fread(file.path(source_dir,'source_rank_inputs.tsv'));rank<-fread(file.path(source_dir,'source_Top10_Top20_lists.tsv'))[method=='UPR_priority'][order(rank)]
gene<-data.table(gene=names(state$primary$point_source),source=as.numeric(state$primary$point_source),RPE1=as.numeric(state$primary$point_validation[names(state$primary$point_source)]))
gene[,Top20:=gene%in%rank$gene];fwrite(gene,file.path(source_data,'Fig_UPR_RPE1_validation_a.tsv'),sep='\t')
rho<-primary[grepl('Spearman',endpoint)]
p_a<-ggplot(gene,aes(source,RPE1))+geom_hline(yintercept=0,linewidth=.25,colour='#CACFD4')+geom_vline(xintercept=0,linewidth=.25,colour='#CACFD4')+geom_point(colour='#9DA4AA',size=.8,alpha=.65)+geom_point(data=gene[Top20==TRUE],colour=blue,size=1.25)+annotate('text',x=-Inf,y=Inf,hjust=-.03,vjust=1.05,label=sprintf('ρ = %.3f\nHolm P = %.5f\n438 genes',rho$estimate,rho$Holm_3_p),size=7/.pt,family=font)+labs(x='K562 UPR contrast (control SD)',y='RPE1 UPR contrast (control SD)')+theme_pub()+theme(legend.position='none')
# Per-gene intervals reuse the locked shared-GEM draws, without new model fitting.
w<-state$primary$validation_wild$effects[rank$gene,,drop=FALSE]
individual<-data.table(gene=rank$gene,rank=rank$rank,mean=state$primary$point_validation[rank$gene],low=apply(w,1,quantile,.025),high=apply(w,1,quantile,.975),Top10=rank$rank<=10)
individual[,label:=sprintf('%02d  %s',rank,gene)];individual[,label:=factor(label,levels=rev(label))]
fwrite(individual,file.path(source_data,'Fig_UPR_RPE1_validation_b.tsv'),sep='\t')
p_b<-ggplot(individual,aes(mean,label))+geom_vline(xintercept=0,linewidth=.3,linetype=2,colour='#929292')+geom_errorbar(aes(xmin=low,xmax=high),orientation='y',width=.2,linewidth=.4,colour=grey)+geom_point(aes(shape=Top10,colour=Top10),size=1.6)+scale_colour_manual(values=c('TRUE'=blue,'FALSE'=ink))+scale_shape_manual(values=c('TRUE'=16,'FALSE'=1))+labs(x='RPE1 UPR contrast (control SD)',y='Frozen source rank')+theme_pub()+theme(legend.position='none',axis.text.y=element_text(size=7))
means<-rbindlist(list(fixed[,.(TopK,group='Selected',mean=selected_mean,low=selected_mean_low,high=selected_mean_high)],fixed[,.(TopK,group='Matched background',mean=background_mean,low=background_mean_low,high=background_mean_high)]))
means[,y:=ifelse(TopK==10,2,1)+ifelse(group=='Selected',.11,-.11)]
fwrite(means,file.path(source_data,'Fig_UPR_RPE1_validation_c.tsv'),sep='\t')
p_c<-ggplot(means,aes(mean,y,colour=group,shape=group))+geom_vline(xintercept=0,linewidth=.3,linetype=2,colour='#929292')+geom_errorbar(aes(xmin=low,xmax=high),orientation='y',width=.1,linewidth=.45)+geom_point(size=1.7)+scale_colour_manual(values=c(Selected=blue,'Matched background'=grey))+scale_shape_manual(values=c(Selected=16,'Matched background'=1))+scale_y_continuous(breaks=1:2,labels=c('Top 20','Top 10'),limits=c(.55,2.45),expand=expansion(mult=0))+labs(x='Mean signed RPE1 UPR contrast (control SD)',y=NULL)+theme_pub()+theme(legend.position='top',legend.direction='horizontal',legend.margin=margin(0,0,0,0),plot.margin=margin(0,4,4,4))
baseline<-fread(file.path(results,'complete_case_baseline_utility.tsv'))[TopK==20&method%in%c('UPR_priority','raw_UPR','generic_magnitude','DepMap')]
labels<-c(UPR_priority='UPR + agreement',raw_UPR='Raw UPR',generic_magnitude='Three-program norm',DepMap='Essentiality')
baseline[,label:=factor(labels[method],levels=rev(unname(labels)))];baseline[,colour:=ifelse(method=='UPR_priority','UPR','Other')]
fwrite(baseline,file.path(source_data,'Fig_UPR_RPE1_validation_d.tsv'),sep='\t')
p_d<-ggplot(baseline,aes(minus_raw_UPR_mean,label))+geom_vline(xintercept=0,linewidth=.3,linetype=2,colour='#929292')+geom_errorbar(aes(xmin=gene_bootstrap_low,xmax=gene_bootstrap_high),orientation='y',width=.14,linewidth=.45,colour=grey)+geom_point(aes(colour=colour,shape=method=='raw_UPR'),size=1.7)+scale_colour_manual(values=c(UPR=blue,Other=ink))+scale_shape_manual(values=c('TRUE'=1,'FALSE'=16))+labs(x='Top-20 mean difference\nfrom raw UPR',y=NULL)+theme_pub()+theme(legend.position='none')
np<-fread(file.path(results,'primary_all100_module_controls.tsv'));nc<-fread(file.path(results,'complete_covariate_all100_module_controls.tsv'))
calp<-fread(file.path(results,'primary_module_specificity_calibration.tsv'));calc<-fread(file.path(results,'complete_covariate_module_specificity_calibration.tsv'))
nulls<-rbindlist(list(np[,.(panel='Correlation (438 genes)',value=signed_rho)],nc[,.(panel='UPR gap (370 genes)',value=Top20_on_real_UPR_matched_gap)]))
observed<-rbindlist(list(calp[calibration=='signed_rho',.(panel='Correlation (438 genes)',value=observed,tail=upper_tail_fraction)],calc[calibration=='Top20_on_real_UPR_matched_gap',.(panel='UPR gap (370 genes)',value=observed,tail=upper_tail_fraction)]))
nulls[,panel:=factor(panel,levels=unique(panel))];observed[,panel:=factor(panel,levels=levels(nulls$panel))]
fwrite(nulls,file.path(source_data,'Fig_UPR_RPE1_validation_e_nulls.tsv'),sep='\t');fwrite(observed,file.path(source_data,'Fig_UPR_RPE1_validation_e_observed.tsv'),sep='\t')
p_e<-ggplot(nulls,aes(value))+stat_ecdf(geom='step',linewidth=.5,colour=grey)+geom_vline(data=observed,aes(xintercept=value),colour=blue,linewidth=.6)+geom_text(data=observed,aes(x=-Inf,y=.87,label=sprintf('Upper tail\n%.4f',tail)),inherit.aes=FALSE,hjust=-.03,vjust=1,size=7/.pt,family=font,colour=ink)+facet_wrap(~panel,ncol=2,scales='free_x')+scale_y_continuous(limits=c(0,1.02),breaks=c(0,.5,1),expand=expansion(mult=0))+scale_x_continuous(n.breaks=3,expand=expansion(mult=c(.04,.04)))+labs(x='ρ (left); matched gap (control SD, right)',y='Fraction of random modules')+theme_pub()+theme(legend.position='none',panel.spacing.x=grid::unit(3,'mm'))
design<-'AB\nCB\nDE'
fig<-p_a+p_b+p_c+p_d+p_e+plot_layout(design=design,widths=c(.92,1.08),heights=c(.95,.60,.85))+plot_annotation(tag_levels='a')&theme(plot.tag=element_text(size=8,face='bold',family=font))
stem<-'Fig_UPR_RPE1_validation';wi<-183/25.4;hi<-178/25.4
svglite::svglite(file.path(archive,paste0(stem,'.svg')),width=wi,height=hi);print(fig);dev.off()
if(Sys.info()[['sysname']]=='Darwin')grDevices::quartz(type='pdf',file=file.path(base,'figure',paste0(stem,'.pdf')),width=wi,height=hi,family=font)else grDevices::cairo_pdf(file.path(base,'figure',paste0(stem,'.pdf')),width=wi,height=hi,family=font)
print(fig);dev.off()
for(resolution in c(300,150)){ragg::agg_png(file.path(archive,paste0(stem,if(resolution==300)'_preview.png'else'_actual_size.png')),width=wi,height=hi,units='in',res=resolution);print(fig);dev.off()}
writeLines(c('Fig. 4 | Source-frozen UPR ordering and relative response prioritization in RPE1.',
'a, Signed source and held-out UPR contrasts across the 438 metadata-eligible genes. Blue points identify the source-fixed Top 20. Scores use the same 6,780-gene normalization universe and 90 UPR members in both contexts, with the targeted member removed where applicable. Correlation was 0.378 (95% gene-bootstrap interval 0.289–0.461; Holm-adjusted P=0.00030). The RPE1 context is from the same published study as K562, not a new independent study.',
'b, All 20 source-ranked genes in fixed source order; filled points identify the first ten. The dashed line denotes zero matched-control contrast. Bars are 95% intervals from the locked shared-GEM wild draws, conditional on measured controls and their SDs. Both directions are retained: 14 of 20 and 9 of 10 selected genes have positive RPE1 contrasts. GEMs are technical partitions, not biological replicates.',
'c, Signed mean RPE1 contrasts for selected genes and their frozen backgrounds (five distinct source-covariate matches per selected gene). Bars are 95% intact-matched-set bootstrap intervals for the individual means. Top 20 mean was 0.044 versus −0.285 in its background; Top 10 mean was 0.243 versus −0.330. The corresponding signed gaps were 0.329 and 0.573 (Holm-adjusted P=0.00040 for each), whereas selected signed-mean intervals and the gaps in absolute-effect magnitude included zero. Relative enrichment therefore does not imply uniform activation or greater absolute programme movement.',
'd, Top 20 mean signed-response differences from raw-UPR ordering on the common 370-gene comparator population; bars are 95% whole-gene bootstrap intervals. Agreement weighting did not demonstrate improvement over raw UPR (difference 0.044; interval −0.018 to 0.117; exploratory Holm P=0.842), and the Top 10 sets were identical. Generic three-program magnitude and essentiality selected lower signed UPR responses. The annotation-derived comparator is reported separately because its 217-way maximum-score tie makes a literal Top 20 ranking arbitrary.',
'e, Fixed 100-module expression/detection-matched controls. Grey curves are empirical distributions; blue lines mark real UPR. Correlation conservation in the full 438-gene panel was not distinguished from random modules (upper-tail fraction 0.109). The uniform pre-outcome complete-covariate sensitivity (370 genes) allowed all 100 null Top 20 matched comparisons; its UPR signed-gap tail fraction was 0.0099. In the full roster only 16 null matched lists were estimable, and none was silently repaired or excluded from the availability report. These computational controls and conditional intervals do not establish a mechanism, functional benefit or universal programme conservation.'),file.path(archive,paste0(stem,'_legend.txt')))
writeLines(c('Archetype: asymmetric quantitative validation figure; ordinal association -> all fixed genes -> signed absolute levels -> simple comparator -> matched module specificity.',
'183x178mm;7pt Helvetica body and8pt bold lowercase panel letters; editable PDF/SVG; R-only previews.',
'All20 genes retained, zero-control references shown, opposite effects retained, both primary and common-covariate populations labeled.',
'PanelC displays signed means, not matched gaps or absolute-response magnitude. PanelD intervals concern differences from rawUPR, not intervals of absolute mean.',
'Biological scope: same-study held-out cellular context, molecular UPR ordering and relative selection; no uniformly positive activation or new-model advantage claimed.',
'Final R-native preview inspection and PDFfont verification remain to be recorded.'),file.path(archive,paste0(stem,'_quality_scope.txt')))
cat('Created183x178mm RPE1 UPR vector figure.\n')
